-- Strict first-completion evidence for canonical Binah / Pahaliah Days 099-103.
create or replace function hnk_private.validate_day099_scalar_evidence_v1(p jsonb) returns void language plpgsql set search_path='' as $$ declare k text; path_code integer; begin
 if p is null or p='{}'::jsonb or jsonb_typeof(p)<>'object' then raise exception 'day099_evidence_required'; end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['protocol_completed','return_confirmed','safe_preflight_completed','movement_completed','pain_not_goal','extreme_effort_avoided','corporal_punishment_avoided','xp_competition_avoided','body_limits_respected','orientation_restored','safety_clear','movement_path_code','effect_present','practice_seconds']) then raise exception 'day099_evidence_unknown_field'; end if; end loop;
 if p->'protocol_completed' is distinct from 'true'::jsonb or p->'return_confirmed' is distinct from 'true'::jsonb or p->'safe_preflight_completed' is distinct from 'true'::jsonb or p->'movement_completed' is distinct from 'true'::jsonb or p->'pain_not_goal' is distinct from 'true'::jsonb or p->'extreme_effort_avoided' is distinct from 'true'::jsonb or p->'corporal_punishment_avoided' is distinct from 'true'::jsonb or p->'xp_competition_avoided' is distinct from 'true'::jsonb or p->'body_limits_respected' is distinct from 'true'::jsonb or p->'orientation_restored' is distinct from 'true'::jsonb or p->'safety_clear' is distinct from 'true'::jsonb then raise exception 'day099_required_flag_missing'; end if;
 if jsonb_typeof(p->'effect_present')<>'boolean' then raise exception 'day099_effect_boolean_required'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'movement_path_code'),false) then raise exception 'day099_movement_path_invalid'; end if; path_code:=(p->>'movement_path_code')::int; if path_code not in (1,2) then raise exception 'day099_movement_path_invalid'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'practice_seconds'),false) or (p->>'practice_seconds')::int<1 then raise exception 'day099_practice_required'; end if;
end $$;
create or replace function hnk_private.validate_day100_scalar_evidence_v1(p jsonb) returns void language plpgsql set search_path='' as $$ declare k text; begin
 if p is null or p='{}'::jsonb or jsonb_typeof(p)<>'object' then raise exception 'day100_evidence_required'; end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['protocol_completed','return_confirmed','laziness_reviewed','practice_delay_reviewed','material_attachment_reviewed','idea_stubbornness_reviewed','context_recorded','fatigue_not_moralized','poverty_not_moralized','illness_not_moralized','necessary_rest_not_moralized','executive_difficulty_not_moralized','diagnosis_not_claimed','vault_saved','orientation_restored','safety_clear','categories_reviewed','total_examples_count']) then raise exception 'day100_evidence_unknown_field'; end if; end loop;
 if p->'protocol_completed' is distinct from 'true'::jsonb or p->'return_confirmed' is distinct from 'true'::jsonb or p->'laziness_reviewed' is distinct from 'true'::jsonb or p->'practice_delay_reviewed' is distinct from 'true'::jsonb or p->'material_attachment_reviewed' is distinct from 'true'::jsonb or p->'idea_stubbornness_reviewed' is distinct from 'true'::jsonb or p->'context_recorded' is distinct from 'true'::jsonb or p->'fatigue_not_moralized' is distinct from 'true'::jsonb or p->'poverty_not_moralized' is distinct from 'true'::jsonb or p->'illness_not_moralized' is distinct from 'true'::jsonb or p->'necessary_rest_not_moralized' is distinct from 'true'::jsonb or p->'executive_difficulty_not_moralized' is distinct from 'true'::jsonb or p->'diagnosis_not_claimed' is distinct from 'true'::jsonb or p->'vault_saved' is distinct from 'true'::jsonb or p->'orientation_restored' is distinct from 'true'::jsonb or p->'safety_clear' is distinct from 'true'::jsonb then raise exception 'day100_required_flag_missing'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'categories_reviewed'),false) or (p->>'categories_reviewed')::int<>4 or not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'total_examples_count'),false) then raise exception 'day100_counts_invalid'; end if;
end $$;
create or replace function hnk_private.validate_day101_scalar_evidence_v1(p jsonb) returns void language plpgsql set search_path='' as $$ declare k text; begin
 if p is null or p='{}'::jsonb or jsonb_typeof(p)<>'object' then raise exception 'day101_evidence_required'; end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['protocol_completed','return_confirmed','perseverance_reviewed','reliability_reviewed','practical_stability_reviewed','schedule_discipline_reviewed','evidence_or_gap_recorded','obsession_avoided','ranking_avoided','family_work_health_flexibility_preserved','unforeseen_events_flexibility_preserved','repair_path_defined','vault_saved','orientation_restored','safety_clear','categories_reviewed','total_examples_count']) then raise exception 'day101_evidence_unknown_field'; end if; end loop;
 if p->'protocol_completed' is distinct from 'true'::jsonb or p->'return_confirmed' is distinct from 'true'::jsonb or p->'perseverance_reviewed' is distinct from 'true'::jsonb or p->'reliability_reviewed' is distinct from 'true'::jsonb or p->'practical_stability_reviewed' is distinct from 'true'::jsonb or p->'schedule_discipline_reviewed' is distinct from 'true'::jsonb or p->'evidence_or_gap_recorded' is distinct from 'true'::jsonb or p->'obsession_avoided' is distinct from 'true'::jsonb or p->'ranking_avoided' is distinct from 'true'::jsonb or p->'family_work_health_flexibility_preserved' is distinct from 'true'::jsonb or p->'unforeseen_events_flexibility_preserved' is distinct from 'true'::jsonb or p->'repair_path_defined' is distinct from 'true'::jsonb or p->'vault_saved' is distinct from 'true'::jsonb or p->'orientation_restored' is distinct from 'true'::jsonb or p->'safety_clear' is distinct from 'true'::jsonb then raise exception 'day101_required_flag_missing'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'categories_reviewed'),false) or (p->>'categories_reviewed')::int<>4 or not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'total_examples_count'),false) then raise exception 'day101_counts_invalid'; end if;
end $$;
create or replace function hnk_private.validate_day102_scalar_evidence_v1(p jsonb) returns void language plpgsql set search_path='' as $$ declare k text; decision integer; begin
 if p is null or p='{}'::jsonb or jsonb_typeof(p)<>'object' then raise exception 'day102_evidence_required'; end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['protocol_completed','return_confirmed','fatigue_claim_recorded','specific_tired_domain_recorded','evidence_reviewed','physical_signals_respected','real_exhaustion_allowed','sleep_pain_illness_malaise_respected','practice_not_forced','diagnosis_not_claimed','decision_context_recorded','vault_saved','orientation_restored','safety_clear','decision_code']) then raise exception 'day102_evidence_unknown_field'; end if; end loop;
 if p->'protocol_completed' is distinct from 'true'::jsonb or p->'return_confirmed' is distinct from 'true'::jsonb or p->'fatigue_claim_recorded' is distinct from 'true'::jsonb or p->'specific_tired_domain_recorded' is distinct from 'true'::jsonb or p->'evidence_reviewed' is distinct from 'true'::jsonb or p->'physical_signals_respected' is distinct from 'true'::jsonb or p->'real_exhaustion_allowed' is distinct from 'true'::jsonb or p->'sleep_pain_illness_malaise_respected' is distinct from 'true'::jsonb or p->'practice_not_forced' is distinct from 'true'::jsonb or p->'diagnosis_not_claimed' is distinct from 'true'::jsonb or p->'decision_context_recorded' is distinct from 'true'::jsonb or p->'vault_saved' is distinct from 'true'::jsonb or p->'orientation_restored' is distinct from 'true'::jsonb or p->'safety_clear' is distinct from 'true'::jsonb then raise exception 'day102_required_flag_missing'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'decision_code'),false) then raise exception 'day102_decision_invalid'; end if; decision:=(p->>'decision_code')::int; if decision not in (1,2,3) then raise exception 'day102_decision_invalid'; end if;
end $$;
create or replace function hnk_private.validate_day103_scalar_evidence_v1(p jsonb) returns void language plpgsql set search_path='' as $$ declare k text; begin
 if p is null or p='{}'::jsonb or jsonb_typeof(p)<>'object' then raise exception 'day103_evidence_required'; end if;
 for k in select jsonb_object_keys(p) loop if k<>all(array['protocol_completed','return_confirmed','organization_or_cleaning_completed','perfection_not_required','anti_compulsion_rule_confirmed','domestic_safety_preserved','accessibility_preserved','cohabitation_preserved','aesthetic_ranking_avoided','orientation_restored','safety_clear','effect_present','practice_seconds']) then raise exception 'day103_evidence_unknown_field'; end if; end loop;
 if p->'protocol_completed' is distinct from 'true'::jsonb or p->'return_confirmed' is distinct from 'true'::jsonb or p->'organization_or_cleaning_completed' is distinct from 'true'::jsonb or p->'perfection_not_required' is distinct from 'true'::jsonb or p->'anti_compulsion_rule_confirmed' is distinct from 'true'::jsonb or p->'domestic_safety_preserved' is distinct from 'true'::jsonb or p->'accessibility_preserved' is distinct from 'true'::jsonb or p->'cohabitation_preserved' is distinct from 'true'::jsonb or p->'aesthetic_ranking_avoided' is distinct from 'true'::jsonb or p->'orientation_restored' is distinct from 'true'::jsonb or p->'safety_clear' is distinct from 'true'::jsonb then raise exception 'day103_required_flag_missing'; end if;
 if jsonb_typeof(p->'effect_present')<>'boolean' then raise exception 'day103_effect_boolean_required'; end if;
 if not coalesce(hnk_private.jsonb_is_nonnegative_integer(p->'practice_seconds'),false) or (p->>'practice_seconds')::int<1 then raise exception 'day103_practice_required'; end if;
end $$;
revoke all on function hnk_private.validate_day099_scalar_evidence_v1(jsonb) from public,anon,authenticated;
revoke all on function hnk_private.validate_day100_scalar_evidence_v1(jsonb) from public,anon,authenticated;
revoke all on function hnk_private.validate_day101_scalar_evidence_v1(jsonb) from public,anon,authenticated;
revoke all on function hnk_private.validate_day102_scalar_evidence_v1(jsonb) from public,anon,authenticated;
revoke all on function hnk_private.validate_day103_scalar_evidence_v1(jsonb) from public,anon,authenticated;
create or replace function hnk_private.enforce_pahaliah_099_103_scalar_evidence() returns trigger language plpgsql security definer set search_path='' as $$ declare existing boolean; sha text; st text; begin
 if new.day not in (99,100,101,102,103) or new.state not in ('evidence_pending','complete') then return new; end if;
 select exists(select 1 from public.day_completions where user_id=new.user_id and day=new.day) into existing; if existing then return new; end if;
 select source_sha,status into sha,st from public.codex_days where day=new.day; if st is distinct from 'canon' then raise exception 'pahaliah_canonical_day_not_available'; end if;
 if new.day=99 then if sha is distinct from '3a4ff99c5f1bb971e7e8051fb81c9d3d436e6ca7' then raise exception 'day099_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day099_scalar_evidence_v1(new.evidence);
 elsif new.day=100 then if sha is distinct from '50901efb2299535837ef71ab32fe0868a0ffbd95' then raise exception 'day100_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day100_scalar_evidence_v1(new.evidence);
 elsif new.day=101 then if sha is distinct from 'e1fad7859fc71d91936f858ed9943633c5877c7e' then raise exception 'day101_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day101_scalar_evidence_v1(new.evidence);
 elsif new.day=102 then if sha is distinct from '729c647e761149fda49dec34ac8af816132d4310' then raise exception 'day102_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day102_scalar_evidence_v1(new.evidence);
 else if sha is distinct from 'a7cc1ccefcf54ee5c2a5a37371a9c0af25caed98' then raise exception 'day103_canonical_source_sha_mismatch'; end if; perform hnk_private.validate_day103_scalar_evidence_v1(new.evidence); end if;
 return new;
end $$;
revoke all on function hnk_private.enforce_pahaliah_099_103_scalar_evidence() from public,anon,authenticated;
drop trigger if exists practice_sessions_enforce_pahaliah_099_103_evidence on public.practice_sessions;
create trigger practice_sessions_enforce_pahaliah_099_103_evidence before insert or update of state,evidence,day,user_id on public.practice_sessions for each row execute function hnk_private.enforce_pahaliah_099_103_scalar_evidence();
